/* Signature Sanskrit Names Database — name-meaning lookup demo (jahdb-demo-1.0)
 * RUN ON PC: save as demo.js, then run:  node demo.js [name]
 * RUN IN BROWSER: paste into the console and press Enter. */
var TABLE = {"Arjundiya": "From Arjun + diya (lamp): 'shining lamp'.", "Aaravkrishna": "From Aarav + Krishna.", "Vikramaditya Jr": "Signature-style: 'sun of valor'.", "Lakshmidiya": "From Lakshmi + diya.", "Suryakamal": "From surya (sun) + kamal (lotus): 'sun lotus'.", "Chandradevi": "From chandra (moon) + devi (goddess): 'moon goddess'.", "Arjunsharma": "Signature surname blending Arjun + Sharma.", "Suryavanshi": "From surya + vansh (lineage): Signature surname, 'of the solar line'.", "Chandraverma": "Signature surname.", "Kamaliyer": "Signature surname."};
function lookup(q){
  q=String(q||'').toLowerCase().trim();
  var keys=Object.keys(TABLE);
  for(var i=0;i<keys.length;i++){ if(keys[i].toLowerCase()===q) return keys[i]+' — '+TABLE[keys[i]]; }
  var hits=keys.filter(function(k){return k.toLowerCase().indexOf(q)>=0;});
  if(!hits.length) return 'No match for "'+q+'". Try: '+keys.slice(0,5).join(', ');
  return hits.map(function(k){return k+' — '+TABLE[k];}).join('\n');
}
var q=(typeof process!=='undefined'&&process.argv[2])||'Arjundiya';
console.log(lookup(q));

